attribute vec3 aO, aE; attribute float aT; attribute vec4 aP; uniform float uTime; varying vec2 vQ; varying float vU, vW, vSeed, vNear;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 6. + .9){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float grow = 1. - pow(1. - clamp(u/.6, 0., 1.), 3.);
      float ang = aP.x + u*.06*(aP.w - .5), r = aP.y*7.0*.92*(.25 + .75*grow);
      vec3 dir = vec3(cos(ang), 0., sin(ang));
      vec3 c = aO + dir*r + vec3(0., aP.z*2. + .16*sin(u*.6 + aP.w*6.), 0.) + vec3(sin(u*.25 + aP.w*9.), 0., cos(u*.21 + aP.w*5.))*.36;
      vec4 mv = viewMatrix*vec4(c, 1.); float S = mix(1.6, 3., aP.w)*(.55 + .45*grow);
